CREATE VIEW std_inventory_resolved AS WITH ranked AS (SELECT *, row_number() OVER (PARTITION BY platform_name, game_title ORDER BY CASE  WHEN ((owned_flag = CAST('t' AS BOOLEAN))) THEN (1) ELSE 0 END DESC, CASE  WHEN ((acquisition_source_raw IS NOT NULL)) THEN (1) ELSE 0 END DESC, CASE  WHEN ((storage_location_raw IS NOT NULL)) THEN (1) ELSE 0 END DESC, CASE  WHEN ((play_status_raw IS NOT NULL)) THEN (1) ELSE 0 END DESC, CASE  WHEN ((igdb_id IS NOT NULL)) THEN (1) ELSE 0 END DESC, CASE  WHEN ((opencritic_id IS NOT NULL)) THEN (1) ELSE 0 END DESC, full_completion_hours DESC NULLS LAST, file_size_gb DESC NULLS LAST) AS duplicate_rank, count() OVER (PARTITION BY platform_name, game_title) AS duplicate_count FROM std_inventory_enriched)SELECT * FROM ranked WHERE (duplicate_rank = 1);
